package Formatter;
use strict;
use warnings;
use POSIX qw(strftime);

sub format_date {
    my ($epoch) = @_;
    return strftime('%Y-%m-%d', gmtime($epoch));
}

1;

package Renderer;
use strict;
use warnings;
use Exporter 'import';
our @EXPORT_OK = qw(render);

# Render a comment into HTML.
sub render {
    my ($text) = @_;
    return "<div class='comment'>" . $text . "</div>";
}

1;
